import android.graphics.SurfaceTexture;import android.graphics.Bitmap;import android.opengl.*;import android.os.*;import android.view.Surface;import android.hardware.display.*;import android.media.projection.MediaProjection;import java.nio.*;import java.util.concurrent.*;
/** One EGL context performs crop and aspect-preserving composition into MediaCodec. */
final class ScreenRenderer implements AutoCloseable {
 private final HandlerThread thread=new HandlerThread("cofra-capture-gl");private Handler handler;private EGLDisplay display;private EGLContext context;private EGLSurface eglSurface;private SurfaceTexture texture;private Surface captureSurface;private VirtualDisplay virtualDisplay;private int program,textureId,sourceW,sourceH,width,height,fps,dpi;private boolean hasFrame,newFrame;private volatile boolean closed;private volatile float top,bottom,side;private long nextFrameNs,lastPreviewNs;private int previewFbo,previewTexture;private boolean previewDisabled;private final float[] transform=new float[16];private ByteBuffer previewBytes;private final java.util.function.Consumer<String> failure;
 ScreenRenderer(float t,float b,float s,java.util.function.Consumer<String> f){top=t;bottom=b;side=s;failure=f;}
 void start(MediaProjection projection,Surface output,int sw,int sh,int density,int w,int h,int rate)throws Exception{sourceW=sw;sourceH=sh;dpi=density;width=w;height=h;fps=rate;thread.start();handler=new Handler(thread.getLooper());CountDownLatch done=new CountDownLatch(1);Throwable[] error={null};handler.post(()->{try{prepare(output);texture.setDefaultBufferSize(sourceW,sourceH);captureSurface=new Surface(texture);texture.setOnFrameAvailableListener(st->{newFrame=true;CaptureService.sourceFrames++;},handler);virtualDisplay=projection.createVirtualDisplay("Cofra Studio · captura",sourceW,sourceH,dpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,captureSurface,null,handler);handler.post(tick);}catch(Throwable e){error[0]=e;}finally{done.countDown();}});if(!done.await(8,TimeUnit.SECONDS)||error[0]!=null)throw new Exception("Não foi possível iniciar a imagem do Android");}
 void resize(int w,int h){if(handler!=null&&!closed&&w>0&&h>0)handler.post(()->{if(w==sourceW&&h==sourceH)return;sourceW=w;sourceH=h;texture.setDefaultBufferSize(w,h);if(virtualDisplay!=null)virtualDisplay.resize(w,h,dpi);});}
 void crop(float t,float b,float s){top=FrameMath.bound(t,.3f);bottom=FrameMath.bound(b,.3f);side=FrameMath.bound(s,.2f);}
 private static FloatBuffer buffer(float[] data){FloatBuffer b=ByteBuffer.allocateDirect(data.length*4).order(ByteOrder.nativeOrder()).asFloatBuffer();b.put(data).position(0);return b;}
 private void prepare(Surface output){display=EGL14.eglGetDisplay(EGL14.EGL_DEFAULT_DISPLAY);int[] v=new int[2];if(!EGL14.eglInitialize(display,v,0,v,1))throw new IllegalStateException();int[] attributes={EGL14.EGL_RED_SIZE,8,EGL14.EGL_GREEN_SIZE,8,EGL14.EGL_BLUE_SIZE,8,EGL14.EGL_RENDERABLE_TYPE,EGL14.EGL_OPENGL_ES2_BIT,0x3142,1,EGL14.EGL_NONE};EGLConfig[] configs=new EGLConfig[1];int[] n=new int[1];EGL14.eglChooseConfig(display,attributes,0,configs,0,1,n,0);if(n[0]<1)throw new IllegalStateException();context=EGL14.eglCreateContext(display,configs[0],EGL14.EGL_NO_CONTEXT,new int[]{EGL14.EGL_CONTEXT_CLIENT_VERSION,2,EGL14.EGL_NONE},0);eglSurface=EGL14.eglCreateWindowSurface(display,configs[0],output,new int[]{EGL14.EGL_NONE},0);if(!EGL14.eglMakeCurrent(display,eglSurface,eglSurface,context))throw new IllegalStateException();
  String vertex="attribute vec2 aPosition;attribute vec2 aUv;uniform mat4 uMatrix;uniform vec2 uScale;uniform vec4 uCrop;varying vec2 vUv;void main(){gl_Position=vec4(aPosition*uScale,0.,1.);vec2 uv=mix(uCrop.xy,uCrop.zw,aUv);vUv=(uMatrix*vec4(uv,0.,1.)).xy;}";
  String fragment="#extension GL_OES_EGL_image_external : require\nprecision mediump float;uniform samplerExternalOES uTexture;varying vec2 vUv;void main(){gl_FragColor=texture2D(uTexture,vUv);}";
  int vs=shader(GLES20.GL_VERTEX_SHADER,vertex),fs=shader(GLES20.GL_FRAGMENT_SHADER,fragment);program=GLES20.glCreateProgram();GLES20.glAttachShader(program,vs);GLES20.glAttachShader(program,fs);GLES20.glLinkProgram(program);int[] ok=new int[1];GLES20.glGetProgramiv(program,GLES20.GL_LINK_STATUS,ok,0);if(ok[0]==0)throw new IllegalStateException();GLES20.glDeleteShader(vs);GLES20.glDeleteShader(fs);int[] ids=new int[1];GLES20.glGenTextures(1,ids,0);textureId=ids[0];GLES20.glBindTexture(GLES11Ext.GL_TEXTURE_EXTERNAL_OES,textureId);GLES20.glTexParameteri(GLES11Ext.GL_TEXTURE_EXTERNAL_OES,GLES20.GL_TEXTURE_MIN_FILTER,GLES20.GL_LINEAR);GLES20.glTexParameteri(GLES11Ext.GL_TEXTURE_EXTERNAL_OES,GLES20.GL_TEXTURE_MAG_FILTER,GLES20.GL_LINEAR);GLES20.glTexParameteri(GLES11Ext.GL_TEXTURE_EXTERNAL_OES,GLES20.GL_TEXTURE_WRAP_S,GLES20.GL_CLAMP_TO_EDGE);GLES20.glTexParameteri(GLES11Ext.GL_TEXTURE_EXTERNAL_OES,GLES20.GL_TEXTURE_WRAP_T,GLES20.GL_CLAMP_TO_EDGE);texture=new SurfaceTexture(textureId);
 }
 private static int shader(int type,String source){int shader=GLES20.glCreateShader(type);GLES20.glShaderSource(shader,source);GLES20.glCompileShader(shader);int[] ok=new int[1];GLES20.glGetShaderiv(shader,GLES20.GL_COMPILE_STATUS,ok,0);if(ok[0]==0)throw new IllegalStateException();return shader;}
 private final FloatBuffer positions=buffer(new float[]{-1,-1,1,-1,-1,1,1,1}),uv=buffer(new float[]{0,0,1,0,0,1,1,1});
 private final Runnable tick=new Runnable(){public void run(){if(closed)return;draw();long now=System.nanoTime(),period=1000000000L/fps;if(nextFrameNs==0||now-nextFrameNs>2*period)nextFrameNs=now;nextFrameNs+=period;handler.postDelayed(this,Math.max(1,(nextFrameNs-System.nanoTime())/1000000));}};
 private void draw(){if(closed)return;try{if(newFrame){texture.updateTexImage();newFrame=false;hasFrame=true;}if(!hasFrame)return;long now=System.nanoTime();GLES20.glViewport(0,0,width,height);GLES20.glClearColor(0,0,0,1);GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT);GLES20.glUseProgram(program);texture.getTransformMatrix(transform);GLES20.glUniformMatrix4fv(GLES20.glGetUniformLocation(program,"uMatrix"),1,false,transform,0);float[] fit=FrameMath.fit(sourceW,sourceH,width,height,top,bottom,side);GLES20.glUniform2f(GLES20.glGetUniformLocation(program,"uScale"),fit[0],fit[1]);GLES20.glUniform4f(GLES20.glGetUniformLocation(program,"uCrop"),fit[2],fit[3],fit[4],fit[5]);int a=GLES20.glGetAttribLocation(program,"aPosition"),b=GLES20.glGetAttribLocation(program,"aUv");positions.position(0);uv.position(0);GLES20.glEnableVertexAttribArray(a);GLES20.glEnableVertexAttribArray(b);GLES20.glVertexAttribPointer(a,2,GLES20.GL_FLOAT,false,0,positions);GLES20.glVertexAttribPointer(b,2,GLES20.GL_FLOAT,false,0,uv);GLES20.glActiveTexture(GLES20.GL_TEXTURE0);GLES20.glBindTexture(GLES11Ext.GL_TEXTURE_EXTERNAL_OES,textureId);GLES20.glUniform1i(GLES20.glGetUniformLocation(program,"uTexture"),0);GLES20.glDrawArrays(GLES20.GL_TRIANGLE_STRIP,0,4);EGLExt.eglPresentationTimeANDROID(display,eglSurface,now);if(!EGL14.eglSwapBuffers(display,eglSurface))throw new IllegalStateException();if(CaptureService.previewWanted&&now-lastPreviewNs>1000000000L&&!previewDisabled){lastPreviewNs=now;preview();}}catch(Exception e){if(!closed){closed=true;failure.accept("O Android interrompeu a captura da imagem.");}}}
 private void preview(){
  final int w=288,h=512;
  try{
   if(previewFbo==0){int[] ids=new int[1];GLES20.glGenTextures(1,ids,0);previewTexture=ids[0];GLES20.glBindTexture(GLES20.GL_TEXTURE_2D,previewTexture);GLES20.glTexImage2D(GLES20.GL_TEXTURE_2D,0,GLES20.GL_RGBA,w,h,0,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,null);GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D,GLES20.GL_TEXTURE_MIN_FILTER,GLES20.GL_LINEAR);GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D,GLES20.GL_TEXTURE_MAG_FILTER,GLES20.GL_LINEAR);GLES20.glGenFramebuffers(1,ids,0);previewFbo=ids[0];GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,previewFbo);GLES20.glFramebufferTexture2D(GLES20.GL_FRAMEBUFFER,GLES20.GL_COLOR_ATTACHMENT0,GLES20.GL_TEXTURE_2D,previewTexture,0);if(GLES20.glCheckFramebufferStatus(GLES20.GL_FRAMEBUFFER)!=GLES20.GL_FRAMEBUFFER_COMPLETE)throw new IllegalStateException();previewBytes=ByteBuffer.allocateDirect(w*h*4).order(ByteOrder.nativeOrder());}
   GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,previewFbo);GLES20.glViewport(0,0,w,h);GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT);GLES20.glDrawArrays(GLES20.GL_TRIANGLE_STRIP,0,4);previewBytes.clear();GLES20.glReadPixels(0,0,w,h,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,previewBytes);IntBuffer pixels=previewBytes.asIntBuffer();int[] colors=new int[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++)colors[(h-y-1)*w+x]=FrameMath.rgbaToArgb(pixels.get(y*w+x));CaptureService.preview=Bitmap.createBitmap(colors,w,h,Bitmap.Config.ARGB_8888);
  }catch(Exception e){previewDisabled=true;}
  finally{GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,0);GLES20.glBindTexture(GLES11Ext.GL_TEXTURE_EXTERNAL_OES,textureId);}
 }
 @Override public void close(){closed=true;if(handler==null)return;CountDownLatch done=new CountDownLatch(1);handler.post(()->{try{if(virtualDisplay!=null)virtualDisplay.release();if(captureSurface!=null)captureSurface.release();if(texture!=null)texture.release();if(display!=null){EGL14.eglMakeCurrent(display,EGL14.EGL_NO_SURFACE,EGL14.EGL_NO_SURFACE,EGL14.EGL_NO_CONTEXT);if(eglSurface!=null)EGL14.eglDestroySurface(display,eglSurface);if(context!=null)EGL14.eglDestroyContext(display,context);EGL14.eglTerminate(display);}thread.quitSafely();}finally{done.countDown();}});try{done.await(2,TimeUnit.SECONDS);}catch(InterruptedException ignored){Thread.currentThread().interrupt();}}
}
